<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount } from 'vue';
import BonusOrb from '../components/BonusOrb.vue';
import EnergyBoostTile from '../components/EnergyBoostTile.vue';
import EnergyAmount from '../components/EnergyAmount.vue';
import EnergyPackArt from '../components/EnergyPackArt.vue';
import GameWindow from '../components/GameWindow.vue';
import GameSwitch from '../components/GameSwitch.vue';
import GameArt from '../components/GameArt.vue';
import GameIcon from '../components/GameIcon.vue';
import RewardedAdGuide from '../components/RewardedAdGuide.vue';
import { state, now, action, walletOperation, openScreen, selectAbility, refreshInvites, moreInvites, request, attemptCost } from '../services/game-store';
import { ensureResourceAge } from '../platform/audience';
import { adsAvailable, adsState, watchRewardedAd, deliverAdReward } from '../services/ads';
import { displayEnergy, rewardMotion } from '../services/energy-motion';
import { starsAvailable, buyStarsProduct, cancelStarsSubscription } from '../services/stars';
const t = (ru: string, en: string) => state.locale === 'ru' ? ru : en;
const page = computed(() => state.screen), wallet = computed(() => state.profile!.wallet);
const clock = ref(now()); const interval = setInterval(() => clock.value = now(), 1000); onBeforeUnmount(() => clearInterval(interval));
const title = computed(() => ({ energy: t('Энергия','Energy'), subscription: t('Увеличить размер бонуса','Increase the bonus amount'), video: t('Энергия за рекламу','Energy for ads'), friends: t('Пригласить друга','Invite a friend'), feedback: t('Обратная связь','Feedback'), packs: t('Купить энергию','Buy energy'), helmet: t('Шлем','Helmet'), jump: t('Прыжок','Jump') }[page.value] ?? ''));
const selectedTier=ref(state.profile?.wallet.energySubscription?.batteryCount??5);
const tierActive=computed(()=>wallet.value.energySubscription&&wallet.value.energySubscription.expiresAt>clock.value?wallet.value.energySubscription.batteryCount:1);
const days=computed(()=>Math.round((state.platform?.stars.periodSec??2592000)/86400));
const bonus = computed(() => wallet.value.simpleBonus), remaining = computed(() => Math.max(0, bonus.value.nextAt - clock.value));
const timer = computed(() => { const s = Math.ceil(remaining.value / 1000); return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`; });
const adUsed=computed(()=>wallet.value.adQuota.resetAt&&clock.value>=wallet.value.adQuota.resetAt?0:wallet.value.adQuota.used);
const adLeft=computed(()=>Math.max(0,wallet.value.adQuota.limit-adUsed.value));
const adCooldown=computed(()=>Math.max(0,(wallet.value.lastAdAt??0)+bonus.value.policy.videoCooldownSec*1000-clock.value));
const adTimer=computed(()=>{const s=Math.ceil(adCooldown.value/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;});
const comment = ref(''), rating = ref<number | null>(null), inviteCode = ref('');
const commentLength=computed(()=>[...comment.value.trim()].length);
const feedbackMinimum=computed(()=>wallet.value.feedbackMinimumSpend??100);
const waiting=(row:any)=>row.bonusStatus==='waiting_google'?t('Ожидается вход через Google','Waiting for Google sign-in'):row.bonusStatus==='waiting_identity'?t('Ожидается подтверждение Telegram','Waiting for Telegram verification'):t('Ожидаются 5 попыток','Waiting for 5 runs');
let taps = 0, tapTimer: ReturnType<typeof setTimeout> | null = null;
const resource = (kind: string, args: Record<string, unknown> = {}) => action(async () => { if (await ensureResourceAge()) await walletOperation(kind, args); });
function headerTap() { if (page.value !== 'energy' || state.busy) return; if (tapTimer) clearTimeout(tapTimer); if (++taps < 5) tapTimer = setTimeout(() => taps = 0, 1500); else { taps = 0; void resource('energy_hidden_tap'); } }
onBeforeUnmount(() => { if (tapTimer) clearTimeout(tapTimer); });
const child = (value: string) => { taps = 0; if(state.busy)return; openScreen(value, 'energy'); if (value === 'friends') void action(refreshInvites); };
onMounted(() => { if (page.value === 'friends') void action(refreshInvites); });
const offers = computed(() => [100,250,500,1000].map(amount => ({ amount, price: state.platform?.stars[`pack${amount}Price` as 'pack100Price'] })));
function copy(text: string) { void navigator.clipboard.writeText(text).then(() => state.notice = t('Скопировано','Copied')).catch(() => state.error = t('Не удалось скопировать. Выделите текст вручную.','Could not copy. Select the text manually.')); }
function nameActions(row:any){if(!row.userId||row.userId===state.profile?.id)return;state.selectedPlayer={userId:row.userId,playerName:row.nickname??t('Игрок','Player')};openScreen('name-actions','friends');}
function shareInvite() { if (state.invites) window.Telegram?.WebApp?.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(state.invites.telegramInviteUrl??state.invites.inviteUrl)}&text=${encodeURIComponent(`${t('Сможете побить мой рекорд в Untouch? Код приглашения:','Can you beat my Untouch record? Invite code:')} ${state.invites.ownCode}`)}`); }
const applyCode = () => action(async () => { if(!await ensureResourceAge())return; await request({ action: 'invites_bind', code: inviteCode.value }); await refreshInvites(); });
</script>
<template>
  <GameWindow :title="title" :tall="!['helmet','jump'].includes(page)" class="energy-window" :data-page="page" :class="{rewarding:rewardMotion.active,'ability-window':['helmet','jump'].includes(page)}">
    <template #title><button class="energy-title-trigger" @click="headerTap">{{ title }}</button></template>
    <template v-if="['energy','packs'].includes(page)" #header-extra><EnergyAmount class="energy-window-balance" :style="{fontSize:`${Math.min(26,170/String(displayEnergy).length)}px`}" :amount="displayEnergy"/><button v-if="page==='energy'" class="icon-button refresh-balance" :aria-label="t('Обновить баланс','Refresh balance')" :disabled="state.busy" @click="action(()=>request({action:'profile'}))">↻</button></template>
    <template v-if="state.parent" #back>‹</template>
    <div v-if="page === 'energy'" class="energy-home">
      <p class="bonus-period">{{ t(`Бонус каждые ${bonus.policy.periodSec/3600} часов`,`Bonus every ${bonus.policy.periodSec/3600} hours`) }}</p>
      <div class="bonus-layout"><BonusOrb :amount="bonus.reward" :ready="remaining===0" :fraction="remaining/(bonus.durationMs||bonus.policy.periodSec*1000)" :timer="timer" :multiplier="tierActive" :pending="state.busy" :locale="state.locale" @claim="resource('energy_bonus_claim')"/><div class="boost-column"><EnergyBoostTile :tier="tierActive" :locale="state.locale" :busy="state.busy" @open="child('subscription')"/><button v-if="tierActive>1" class="text-button boost-manage" :disabled="state.busy" @click="child('subscription')">{{t('Управлять','Manage')}}</button><small v-else>{{t('Подписка','Subscription')}}</small></div></div>
      <div class="energy-reward-row"><GameIcon class="reward-symbol" name="video"/><span>{{ t('Смотреть рекламу','Watch an ad') }}</span><EnergyAmount :amount="bonus.policy.videoReward" prefix="+"/><button class="secondary" :disabled="adLeft===0||adCooldown>0" @click="child('video')">{{ adLeft===0?t('До завтра','Tomorrow'):adCooldown>0?adTimer:t('Смотреть','Watch') }}</button></div>
      <small class="ad-daily-status">{{ t('Сегодня','Today') }}: {{ adUsed }} / {{ wallet.adQuota.limit }}</small>
      <div class="energy-reward-row"><GameIcon class="reward-symbol" name="invite"/><span>{{ t('Пригласить друга','Invite a friend') }}</span><EnergyAmount :amount="bonus.policy.inviterReward" prefix="+"/><button class="secondary" @click="child('friends')">{{ t('Пригласить','Invite') }}</button></div>
      <div class="energy-reward-row"><GameIcon class="reward-symbol" name="feedback"/><span>{{ t('Ваш опыт игры','Your experience') }}</span><EnergyAmount :amount="wallet.energyConfig.rewards.feedback" prefix="+"/><button class="secondary" @click="child('feedback')">{{ wallet.claimed.includes('energy_feedback')?t('Получено','Received'):wallet.feedbackSpentEnergy>=feedbackMinimum?t('Рассказать','Share'):`${wallet.feedbackSpentEnergy}/${feedbackMinimum}` }}</button></div>
      <button class="primary full" @click="child('packs')"><GameIcon name="add"/> {{ t('Купить энергию','Buy energy') }}</button>
    </div>
    <div v-else-if="page === 'helmet' || page === 'jump'" class="ability-page">
      <GameArt class="ability-art" :src="`/assets/branding/ui/simple-energy-${page}.png`" />
      <template v-if="page==='helmet'"><h2>{{ t('Защита от одного удара','Protection from one hit') }}</h2><p class="ability-description">{{ t('Барьер принимает первый удар за попытку.','The barrier absorbs the first hit of a run.') }}</p></template>
      <template v-else><p class="ability-instructions">{{ t('Управляйте одним пальцем. Коснитесь экрана вторым — кубик подпрыгнет.','Control with one finger. Touch with a second finger to jump.') }}</p><p class="ability-detail">{{ t('В прыжке защита от врагов. Опасные стены остаются опасными.','Jumping protects from enemies. Dangerous walls remain dangerous.') }}</p><small class="desktop-jump">{{ t('На компьютере — пробел.','On desktop, press Space.') }}</small></template>
      <hr class="neon-divider">
      <label class="ability-switch-row"><strong>{{ page==='helmet'?t('Включить шлем','Enable helmet'):t('Включить прыжок','Enable jump') }}</strong><GameSwitch :model-value="state[page as 'helmet'|'jump']" :disabled="state.busy" @update:model-value="selectAbility(page as 'helmet'|'jump',$event)" /></label>
      <div class="cost-label"><EnergyAmount :amount="page==='helmet'?wallet.energyConfig.helmetExtraCost:wallet.energyConfig.jumpExtraCost" prefix="+"/> {{ t('к стоимости попытки','per attempt') }}</div>
      <hr class="neon-divider"><p class="next-attempt-cost">{{ t('Следующая попытка стоит','Next attempt costs') }} <EnergyAmount :amount="attemptCost"/></p>
    </div>
    <div v-else-if="page === 'subscription'">
      <p class="intro">{{ t(`Бонус с одной кнопки каждые ${bonus.policy.periodSec/3600} часов`,`One button, every ${bonus.policy.periodSec/3600} hours`) }}</p>
      <button v-for="tier in [2,5]" :key="tier" class="subscription-option full" :class="{selected:selectedTier===tier}" :aria-pressed="selectedTier===tier" :disabled="state.busy" @click="selectedTier=tier"><span class="tier-radio">{{ selectedTier===tier?'◉':'○' }}</span><strong class="gold-medallion">×{{tier}}</strong><span class="tier-reward"><EnergyAmount :amount="tier===2?state.config!.config.economy.androidEnergyV2.simpleBonus.tier2Reward:state.config!.config.economy.androidEnergyV2.simpleBonus.tier5Reward"/><small>{{ t('за один бонус','per bonus') }}</small><small v-if="tierActive===tier" class="mint">{{t('Подключено','Active')}}</small></span><span class="tier-price">{{ tier===2?state.platform?.stars.tier2Price??'—':state.platform?.stars.tier5Price??'—' }} ★<small>/ {{days}} {{t('дней','days')}}</small></span></button>
      <p class="subscription-ad-policy">♧ {{ t('Без автоматической рекламы','No automatic ads') }}<small>{{ t('Доступность видео за энергию проверяется отдельно.','Rewarded video availability is checked separately.') }}</small></p>
      <button class="primary full subscribe-action" :disabled="!starsAvailable()||state.busy||tierActive>1" @click="action(()=>buyStarsProduct(`energy_batteries_${selectedTier}_v1`))">{{ tierActive===selectedTier?t('Подключено','Active'):t(`Подключить ×${selectedTier}`,`Subscribe ×${selectedTier}`) }}<small>{{ t(`${days} дней · автопродление`,`${days} days · auto-renewal`) }}</small></button>
      <p v-if="!starsAvailable()" class="hint">{{ t('Покупки пока недоступны.','Purchases are not available yet.') }}</p>
      <template v-if="wallet.energySubscription?.provider==='telegram'&&wallet.energySubscription.expiresAt>clock"><p>{{ t('Активно до','Active until') }} {{ new Date(wallet.energySubscription.expiresAt).toLocaleDateString(state.locale) }} · {{ wallet.energySubscription.autoRenew?t('Автопродление включено','Auto-renewal on'):t('Без продления','Will not renew') }}</p><button v-if="wallet.energySubscription.autoRenew" class="text-button full" :disabled="state.busy" @click="action(cancelStarsSubscription)">{{ t('Отключить автопродление','Turn off auto-renewal') }}</button></template>
    </div>
    <div v-else-if="page === 'packs'"><div class="pack-grid"><div v-for="(offer,i) in offers" :key="offer.amount" class="energy-pack-card"><EnergyAmount :amount="offer.amount"/><EnergyPackArt :beams="[1,3,5,7][i]!"/><button class="secondary full" :disabled="!starsAvailable()||state.busy" @click="action(()=>buyStarsProduct(`energy_${offer.amount}_v1`))">{{ offer.price??'—' }} ★</button></div></div><p class="pack-provider">♙ {{ t('Оплата через Telegram Stars','Pay with Telegram Stars') }}</p><p v-if="!starsAvailable()" class="hint">{{ t('Покупки пока недоступны.','Purchases are not available yet.') }}</p></div>
    <div v-else-if="page === 'video'" class="center-page"><RewardedAdGuide :reward="bonus.policy.videoReward" :locale="state.locale"/><button v-if="adsState.pending" class="primary full" :disabled="state.busy" @click="action(deliverAdReward)">{{ t('Получить награду за просмотр','Collect viewing reward') }}</button><button v-else class="primary full" :disabled="state.busy||adsState.showing||!adsAvailable()||adLeft===0||adCooldown>0" @click="action(watchRewardedAd)">{{ adLeft===0?t('Лимит на сегодня','Daily limit reached'):adCooldown>0?adTimer:adsAvailable()?t('Посмотреть видео','Watch video'):t('Реклама пока недоступна','Ads are not available yet') }}</button><button class="text-button full" :disabled="state.busy||adsState.showing" @click="openScreen('energy')">{{t('Не сейчас','Not now')}}</button><p class="hint">{{ t('По нажатию откроется реклама AdsGram. Просмотр добровольный; досрочное закрытие не даёт награду.','Tapping opens an AdsGram advertisement. Viewing is optional; closing early gives no reward.') }}</p></div>
    <div v-else-if="page === 'feedback'"><div v-if="wallet.claimed.includes('energy_feedback')" class="center-page feedback-sent"><GameIcon name="chat-check"/><h2>{{ t('Спасибо! Ваш отзыв принят.','Thank you! We received your feedback.') }}</h2><strong class="chart-total mint"><EnergyAmount :amount="wallet.energyConfig.rewards.feedback" prefix="+"/></strong><button class="secondary full" @click="openScreen('energy')">{{ t('К энергии','Back to energy') }}</button></div><div v-else-if="wallet.feedbackSpentEnergy<feedbackMinimum" class="feedback-locked"><GameIcon name="gamepad"/><h2>{{ t('Сначала познакомьтесь с игрой','Get to know the game first') }}</h2><p>{{ t(`Расскажите об игре после траты ${feedbackMinimum} энергии. За первый отзыв — ${wallet.energyConfig.rewards.feedback} энергии. Любое честное мнение одинаково ценно.`,`Share your experience after spending ${feedbackMinimum} energy. Your first feedback earns ${wallet.energyConfig.rewards.feedback} energy. Every honest opinion is equally welcome.`) }}</p><progress class="feedback-progress" :max="feedbackMinimum" :value="wallet.feedbackSpentEnergy" :aria-label="t('Потрачено энергии','Energy spent')"></progress><p>{{ t('Потрачено','Spent') }}: {{ wallet.feedbackSpentEnergy }} / {{ feedbackMinimum }}</p></div><template v-else><p>{{ t('Что понравилось и что стоит улучшить? Награда не зависит от оценки.','What did you enjoy, and what could be improved? Your rating does not affect the reward.') }}</p><div class="rating-row"><button v-for="n in 5" :key="n" :class="{selected:rating===n}" :aria-pressed="rating===n" :aria-label="`${n} / 5`" @click="rating=rating===n?null:n">{{n}} ★</button></div><small class="rating-hint">{{ t('Оценка по желанию. Награда одинакова.','Rating is optional. The reward stays the same.') }}</small><label class="field-label">{{ t('Впечатления','Your impressions') }}<textarea v-model="comment" minlength="20" maxlength="1000" rows="4"></textarea></label><small>{{ commentLength }} / 1000 · {{ t('не менее 20 символов','at least 20 characters') }}</small><div class="feedback-reward"><span>{{t('За первый отзыв','For your first feedback')}}</span><EnergyAmount :amount="wallet.energyConfig.rewards.feedback" prefix="+"/></div><button class="primary full" :disabled="state.busy||commentLength<20||commentLength>1000" @click="resource('energy_feedback',{comment:comment.trim(),...(rating?{rating}:{})})">{{ wallet.claimed.includes('energy_feedback')?t('Спасибо!','Thank you!'):t('Отправить','Submit') }}</button></template></div>
    <div v-else-if="page === 'friends'" class="friends-page">
      <label class="field-label invite-code">{{ t('Ваш код','Your code') }}<span class="copy-line"><input readonly :value="state.invites?.ownCode??'—'"><button class="icon-button" :aria-label="t('Копировать код','Copy code')" :disabled="!state.invites" @click="copy(state.invites!.ownCode)"><GameIcon name="copy"/></button></span></label>
      <label class="field-label invite-link">{{ t('Ссылка для Telegram','Telegram invitation link') }}<span class="copy-line"><input readonly :value="state.invites?.telegramInviteUrl??'—'"><button class="icon-button" :aria-label="t('Копировать ссылку Telegram','Copy Telegram link')" :disabled="!state.invites?.telegramInviteUrl" @click="copy(state.invites!.telegramInviteUrl!)"><GameIcon name="copy"/></button><button class="icon-button" :aria-label="t('Поделиться','Share')" :disabled="!state.invites?.telegramInviteUrl" @click="shareInvite"><GameIcon name="share"/></button></span></label>
      <details class="android-invite-link"><summary>{{t('Ссылка для Android','Android invitation link')}}</summary><span class="copy-line"><input readonly :value="state.invites?.inviteUrl??'—'"><button class="icon-button" :aria-label="t('Копировать ссылку Android','Copy Android link')" :disabled="!state.invites" @click="copy(state.invites!.inviteUrl)"><GameIcon name="copy"/></button></span></details>
      <hr class="neon-divider"><div class="invite-totals"><span>{{t('Приглашено','Invited')}}<strong>{{state.invites?.invitedCount??'—'}}</strong></span><span>{{t('Получено','Received')}}<EnergyAmount :amount="state.invites?.rewardTotal??0"/></span></div><hr class="neon-divider">
      <h2>{{t('Приглашённые друзья','Invited friends')}}</h2><p class="hint">{{ t('Награда после 5 попыток друга и подтверждения входа Google или Telegram у обоих игроков. Код общий для двух платформ.','Rewards follow 5 runs by your friend and verified Google or Telegram sign-in for both players. The code works on both platforms.') }}</p>
      <ul class="invite-list"><li v-for="row in state.invites?.paidRows" :key="row.id"><button class="public-name-button" @click="nameActions(row)">{{ row.nickname??t('Игрок','Player') }}</button><EnergyAmount :amount="row.amount??row.energyEquivalent??0" prefix="+"/></li><li v-for="row in state.invites?.pendingRows" :key="row.id"><button class="public-name-button" @click="nameActions(row)">{{ row.nickname??t('Игрок','Player') }}</button><span>{{ row.games }} / 5<small>{{ row.platform==='telegram'?'Telegram':'Android' }} · {{ row.identityReady?t('Вход подтверждён ✓','Sign-in verified ✓'):waiting(row) }}</small></span></li><li v-if="state.invites&&!state.invites.paidRows.length&&!state.invites.pendingRows.length" class="empty">{{t('Пока нет приглашённых друзей','No invited friends yet')}}</li><li v-if="state.invites?.nextCursor"><button class="secondary full" :disabled="state.busy" @click="action(moreInvites)">{{t('Показать ещё','Show more')}}</button></li></ul>
      <details class="inviter-section"><summary>{{t('Кто пригласил вас','Who invited you')}}</summary><label class="field-label">{{t('Код приглашения','Invite code')}}<span class="copy-line"><input v-model="inviteCode" :placeholder="state.invites?.inviterCode??t('Введите код','Enter a code')" :disabled="state.invites?.inviterAssigned" maxlength="12"><button class="secondary" :disabled="state.busy||!inviteCode||state.invites?.inviterAssigned" @click="applyCode">{{t('Применить','Apply')}}</button></span></label><p class="hint">{{t('Ваш прогресс','Your progress')}}: {{state.invites?.completedGames??0}} / 5</p><p v-if="state.invites?.inviterAssigned" class="hint">{{t('Код пригласившего уже закреплён.','The inviter is already assigned.')}}</p></details>
    </div>
    
    
  </GameWindow>
</template>
